from lib import *
S = SS('t18')
steps = [
    step("基线:不加任何保护的读—改—写。8 个线程各给同一行加 100 次(应得 800),最终余额只有 103,丢了 697 次更新(87%)。每个线程都先读出余额、算出加 1 之后的值再写回,别人在中间写入的更新被覆盖了。这是后面所有办法要解决的问题。", t=tl(S(1)), mark=lidx(S(1), '最终余额 103'), b=bars([['应得', 800, '800'], ['实际', 103, '103']], 800, mark=[1], done=[0]), kv=KV([['读改写', '没有保护'], ['结果', '800 次只剩 103'], ['原因', '后写的覆盖了先写的']], ['结果'])),
    step("乐观锁:读出 version,更新时带上 WHERE version = ?,更新行数为 0 就是冲突,重读重试。同样 8 个线程各加 100 次:最终余额 800,丢 0 次。代价是重试:共 5619 次尝试才成功 800 次,平均每次成功要试 7.02 次,p99 是 106 次,最多 189 次,4819 次尝试因为 version 变了而更新 0 行(白做)。用时 0.55 s(1444 成功/秒),延迟 p99 84.93 ms。乐观锁保证了正确,代价是冲突多时大量白做。", t=tl(S(2)), mark=lidx(S(2), '5619 次尝试'), done=lidx(S(2), '最终余额 800'), b=bars([['成功次数', 800, '800'], ['总尝试次数', 5619, '5619'], ['白做的尝试', 4819, '4819']], 5700, done=[0], cur=[1], mark=[2]), kv=KV([['正确性', '800,丢 0 次'], ['平均尝试', '每次成功试 7.02 次'], ['白做', '4819 次因 version 变了作废']], ['白做'])),
    step("冲突程度的影响:同一行上并发线程数从 1 到 32,每个线程 200 次(2 轮取中位数)。乐观锁每次成功要试的次数随线程数上升——1 个线程 1.00 次、2 个 1.71、4 个 3.57、8 个 7.03、16 个 13.94、32 个 27.57,吞吐从 4573 降到 417 成功/秒。SELECT ... FOR UPDATE 在 5041 到 6359 操作/秒之间,原子 UPDATE 在 6122 到 8485 之间,线程再多也没有明显下降:加锁让冲突的请求排队,而不是重做。", t=tl(S(3)), mark=lidx(S(3), '32    |', '16    |'), done=lidx(S(3), '1     |', '2     |'), b=bars([['乐观锁 1 线程 成功/秒', 4573, '4573'], ['乐观锁 32 线程 成功/秒', 417, '417'], ['FOR UPDATE 32 线程 操作/秒', 5041, '5041'], ['原子 UPDATE 32 线程 操作/秒', 7188, '7188']], 7200, mark=[1], done=[2, 3], cur=[0]), kv=KV([['乐观锁', '线程越多越白做(27.57 次/成功)'], ['FOR UPDATE', '排队,吞吐稳定'], ['原子 UPDATE', '吞吐最高']], ['乐观锁'])),
    step("低冲突:32 个线程各用自己的一行(没有冲突)。乐观锁 8958 操作/秒,平均每次成功试 1.00 次(一次就成功);SELECT ... FOR UPDATE 9958 操作/秒,两者在同一个量级。没有冲突时乐观锁不需要任何等待,它的价值就在“冲突少”的场景。", t=tl(S(4)), mark=lidx(S(4), '乐观锁'), done=lidx(S(4), 'FOR UPDATE'), b=bars([['乐观锁 操作/秒', 8958, '8958'], ['FOR UPDATE 操作/秒', 9958, '9958']], 10000, cur=[0, 1]), kv=KV([['乐观锁', '一次就成功(1.00 次)'], ['FOR UPDATE', '同一量级'], ['适合', '冲突少的场景']], ['适合'])),
    step("ABA:订单状态 PAID → REFUNDED → PAID(换了一张新的支付单),发货方在读到 PAID 之后、更新之前,这两步都发生了。按状态值做 CAS(WHERE status = 'PAID'):300 次试验里有 208 次,发货那一刻订单上的支付单已经不是发货方看到的那张(原单已经退款),也就是按旧支付单发了货;按 version 做 CAS(WHERE version = ?):0 次——version 每次改动都会增加、不会“变回去”,冲突被发现,发货方重读后看到新的支付单。状态值回到了“PAID”,CAS 看不出中间发生过什么。", t=tl(S(5)), mark=lidx(S(5), '按状态值 CAS'), done=lidx(S(5), '按 version CAS'), b=bars([['状态值 CAS:发货依据过期支付单的次数', 208, '208 / 300'], ['version CAS:发货依据过期支付单的次数', 0, '0 / 300']], 300, mark=[0], done=[1]), kv=KV([['状态值 CAS', '看不出 A→B→A'], ['version CAS', '每次改动都递增'], ['后果', '按退款的旧支付单发了货']], ['后果'])),
    step("高冲突下的重试风暴:32 个线程抢同一行(各 200 次)。无退避(失败立刻重试):409 成功/秒,平均每次成功试 27.30 次,p99 1484.1 ms,每轮白做了 168318 次尝试。加随机指数退避(基数 0.2 ms):3332 成功/秒,平均 2.49 次,p99 169.7 ms,白做降到 9544 次。冲突严重时立刻重试等于用无效请求把数据库打满;随机退避让重试错开,总吞吐反而高了 8 倍。", t=tl(S(6)), mark=lidx(S(6), '无退避'), done=lidx(S(6), '随机指数退避'), b=bars([['无退避 成功/秒', 409, '409'], ['随机退避 成功/秒', 3332, '3332'], ['无退避 平均每次成功试', 27.30, '27.30'], ['随机退避 平均每次成功试', 2.49, '2.49']], 3400, mark=[0, 2], done=[1, 3]), kv=KV([['无退避', '27.30 次/成功,p99 1484 ms'], ['随机指数退避', '2.49 次/成功,p99 170 ms'], ['吞吐', '409 → 3332 成功/秒']], ['随机指数退避'])),
]
A = mkartt('t18', 18, '分布式事务,乐观锁,CAS,version,ABA,MySQL,真实验证,动画演示',
    '实测乐观锁:不保护的读改写 800 次丢 697 次;version CAS 丢 0 次,但同一行 8 线程每次成功平均试 7.02 次、32 线程 27.57 次,吞吐从 4573 降到 417 成功/秒;无冲突时一次成功;按状态值 CAS 有 208 / 300 次被 ABA 欺骗,version CAS 0 次;随机指数退避把 409 提高到 3332 成功/秒。',
    '乐观锁用一个 version 做比较并交换,不加锁就能防住丢失更新。它在什么情况下好用、什么情况下白做、能不能被 ABA 欺骗、冲突严重时怎么重试?这篇用真实的 MySQL,把这几个问题的数字逐一量出来。',
    [('697 → 0', '8 个线程各加 100 次:不保护丢的更新次数 → version CAS 丢的次数'), ('1.00 → 27.57', '同一行上并发线程数从 1 到 32,乐观锁每次成功平均要试的次数'), ('208 / 0', '300 次 ABA 试验里,按状态值 CAS 与按 version CAS 被过期的支付单欺骗的次数')],
    [('丢失更新', '<p>读出后在应用里算再写回,别人的更新会被覆盖,800 次只剩 103。</p>'),
     ('version CAS', '<p>UPDATE ... WHERE version = ?,0 行就是冲突,重读重试;结果正确,代价是白做的尝试。</p>'),
     ('冲突越多越白做', '<p>同一行线程数翻倍,每次成功要试的次数大约翻倍;悲观加锁让请求排队,吞吐稳定。</p>'),
     ('低冲突', '<p>没有冲突时乐观锁一次成功,和悲观锁同一量级。</p>'),
     ('ABA', '<p>按状态值做 CAS 看不出 PAID → REFUNDED → PAID 中间发生过什么;version 每次改动都递增,不会变回去。</p>'),
     ('重试要退避', '<p>冲突严重时无退避的重试把数据库打满,随机指数退避让总吞吐高 8 倍。</p>')],
    steps,
    [ENV_T + '。本篇用一个 MySQL 26.7.0 实例(默认 REPEATABLE-READ),PyMySQL,每个线程一个连接;吞吐是 2 轮取中位数(第三节)或单次(其它);第五节的“A 读到 PAID 之后、更新之前 B 做退款并重新支付”是用线程和随机延迟(0~10 ms 与 0~6 ms)造的交错,不是从真实业务抓来的',
     '没有验证:SERIALIZABLE 或 READ COMMITTED 下的差别;多行 / 多表的乐观锁(只测了单行);ORM(如 JPA 的 @Version)的行为;乐观锁与悲观锁在长事务下的差别;重试次数上限与放弃策略;退避基数 0.2 ms 是我设的,没有调参'],
    '乐观锁')
